let settings={shippingFee:3000,cancelHours:24,shippingNotice:'주 1회 모아서 발송합니다. 주간 마감과 발송일은 렛츠런플레이 상품 상세 안내를 확인해 주세요.',...JSON.parse(localStorage.goodsSettings||'{}')};
