let salesTab='orders',detailOrder=null;
const dateText=o=>o.createdAt?new Date(o.createdAt).toLocaleString('ko-KR'):o.date||'—';
const state=o=>o.status==='출고 대기'?'배송 준비 중':o.status==='출고 완료'?'발송 완료':o.status==='전체 취소'?'취소 완료':o.status;
function persist(){localStorage.goodsOrders=JSON.stringify(orderData);localStorage.goodsProducts=JSON.stringify(goods);localStorage.goodsSettings=JSON.stringify(settings);}
function notify(message){$('adminStatus').textContent=message;}
function filteredOrders(){const keyword=$('keyword').value.trim().toLowerCase(),payment=$('paymentFilter').value,ship=$('shippingFilter').value;return orderData.filter(o=>{const date=o.createdAt?new Date(o.createdAt):null;const day=date?`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`:'';return (salesTab!=='shipping'||o.status==='출고 대기')&&(!keyword||[o.number,o.name,o.phone,o.recipient].join(' ').toLowerCase().includes(keyword))&&(!payment||(payment==='cancelled'?o.status==='전체 취소':o.status!=='전체 취소'))&&(!ship||o.status===ship)&&(!$('startDate').value||day>=$('startDate').value)&&(!$('endDate').value||day<=$('endDate').value);});}
function invoiceCell(o){
 if(o.status==='전체 취소')return '<span class="form-note">취소된 주문</span>';
 if(!['출고 대기','출고 완료','배송 완료'].includes(o.status))return '<span class="form-note">송장 등록 불가</span>';
 return `<div class="invoice-inline"><select class="invoice-carrier" aria-label="${esc(o.number)} 택배사">${carrierNames.map(c=>`<option ${c===(o.carrier||$('defaultCarrier').value)?'selected':''}>${c}</option>`).join('')}</select><div class="invoice-entry"><input class="tracking-input" inputmode="numeric" aria-label="${esc(o.number)} 송장번호" placeholder="송장번호 입력" value="${esc(o.trackingNumber||'')}"><button class="invoice-save" aria-label="${esc(o.number)} 송장 ${o.trackingNumber?'수정':'등록'}">${o.trackingNumber?'수정':'등록'}</button>${o.trackingNumber?`<a class="invoice-lookup" href="https://search.naver.com/search.naver?query=${encodeURIComponent((o.carrier||'')+' '+o.trackingNumber+' 배송조회')}" target="_blank" rel="noopener noreferrer" title="네이버에서 배송 조회">조회 ↗</a>`:''}</div><p class="invoice-row-error" role="alert"></p></div>`;
}
function renderOrders(){
 const rows=filteredOrders(),shipping=salesTab==='shipping';$('pendingCount').textContent=orderData.filter(o=>o.status==='출고 대기').length;$('resultCount').textContent=rows.length;$('listTitle').firstChild.textContent=shipping?'발송 대기 주문 ':'상품 주문 목록 ';$('listHint').textContent=shipping?'택배사와 송장번호를 확인한 뒤 등록 버튼 또는 Enter로 발송 처리합니다.':'송장 등록·수정은 주문 행에서 바로 진행할 수 있습니다.';$('shippingToolbar').hidden=!shipping;$('pageCount').textContent=`${rows.length?'1–'+rows.length:'0'} / ${rows.length}건`;
 $('ordersTable').innerHTML=rows.length?`<table><thead><tr><th>주문번호</th><th>구매자</th><th>주문상품</th>${shipping?'<th>배송지</th>':'<th>결제금액</th><th>결제 · 환불</th>'}<th>배송 상태</th><th>송장 정보</th><th>상세</th></tr></thead><tbody>${rows.map(o=>`<tr data-number="${esc(o.number)}"><td><b>${esc(o.number)}</b>${shipping?'':`<small>${esc(dateText(o))}</small>`}</td><td><b>${esc(o.name)}</b><small>${esc(o.phone)}</small></td><td>${o.items.map(i=>`${esc(i.name)} <b>× ${i.qty}</b>`).join('<br>')}</td>${shipping?`<td>${esc(o.recipient||o.name)}<small>${esc(o.address)}</small><small>${esc(o.request||'')}</small></td>`:`<td><b>${money(o.total)}</b></td><td><span class="badge ${o.status==='전체 취소'?'grey':''}">${o.status==='전체 취소'?'전액 환불 완료':'결제 완료'}</span></td>`}<td><span class="badge ${o.status==='전체 취소'?'grey':o.status==='출고 완료'||o.status==='배송 완료'?'green':''}">${esc(state(o))}</span></td><td>${invoiceCell(o)}</td><td><button data-detail="${esc(o.number)}">상세보기</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">조건에 맞는 주문이 없습니다.</div>';
 document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>showDetail(b.dataset.detail));
 document.querySelectorAll('.invoice-save').forEach(b=>b.onclick=()=>saveRowInvoice(b.closest('tr')));
 document.querySelectorAll('.tracking-input').forEach(input=>input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();saveRowInvoice(input.closest('tr'));}});
}
function saveRowInvoice(row){
 const error=row.querySelector('.invoice-row-error');error.textContent='';
 try{
  const stored=localStorage.getItem('goodsOrders'),latest=stored===null?orderData:JSON.parse(stored);if(!Array.isArray(latest))throw Error('주문 데이터를 확인해 주세요.');
  const order=latest.find(o=>o.number===row.dataset.number);if(!order||!['출고 대기','출고 완료','배송 완료'].includes(order.status))throw Error('현재 상태에서는 송장을 등록할 수 없습니다. 목록을 다시 확인해 주세요.');
  const carrier=row.querySelector('.invoice-carrier').value,trackingNumber=row.querySelector('.tracking-input').value.trim().replace(/[\s-]/g,'');
  if(!carrierNames.includes(carrier))throw Error('택배사를 선택해 주세요.');if(!/^\d{8,30}$/.test(trackingNumber))throw Error('송장번호는 숫자 8~30자리로 입력해 주세요.');
  if(latest.some(o=>o.number!==order.number&&o.status!=='전체 취소'&&o.carrier===carrier&&String(o.trackingNumber||'').replace(/[\s-]/g,'')===trackingNumber))throw Error('다른 주문에 등록된 송장번호입니다.');
  if(order.carrier===carrier&&order.trackingNumber===trackingNumber)return;
  const time=Date.now(),updated=latest.map(o=>o.number===order.number?{...o,carrier,trackingNumber,status:o.status==='출고 대기'?'출고 완료':o.status,shippedAt:o.shippedAt||time,shipmentHistory:[...(o.shipmentHistory||[]),{at:time,action:o.trackingNumber?'송장 수정':'송장 등록',previousCarrier:o.carrier||'',previousTrackingNumber:o.trackingNumber||'',carrier,trackingNumber}]}:o);
  localStorage.setItem('goodsOrders',JSON.stringify(updated));orderData=updated;renderOrders();notify('');
 }catch(e){error.textContent=e.message||'저장하지 못했습니다. 다시 시도해 주세요.';}
}
function showDetail(number){detailOrder=orderData.find(o=>o.number===number);const o=detailOrder;if(!o)return;$('orderDetail').innerHTML=`<p><b>${esc(o.number)}</b> <span class="badge">${esc(state(o))}</span></p><p class="form-note">${esc(dateText(o))}</p><section class="detail-section"><h3>주문상품</h3><div class="detail-box">${o.items.map(i=>`<p class="detail-cost"><span>${esc(i.name)} × ${i.qty}</span><b>${i.price!=null?money(i.price*i.qty):'—'}</b></p>`).join('')}</div></section><section class="detail-section"><h3>회원 · 배송정보</h3><div class="detail-box"><p><b>${esc(o.recipient||o.name)}</b> · ${esc(o.recipientPhone||o.phone)}</p><p>${esc(o.address)} ${esc(o.postcode||'')}</p><p>배송메모: ${esc(o.request||'없음')}</p>${o.trackingNumber?`<p>${esc(o.carrier||'택배사 미등록')} · ${esc(o.trackingNumber)}</p>`:''}</div></section>${o.shipmentHistory?.length?`<section class="detail-section"><h3>송장 변경 이력</h3><div class="detail-box">${o.shipmentHistory.map(h=>`<p>${esc(new Date(h.at).toLocaleString('ko-KR'))} · ${esc(h.action)}<br>${h.previousTrackingNumber?esc(h.previousCarrier+' '+h.previousTrackingNumber)+' → ':''}${esc(h.carrier)} · ${esc(h.trackingNumber)}</p>`).join('')}</div></section>`:''}<section class="detail-section"><h3>결제정보</h3><div class="detail-box"><p class="detail-cost"><span>상품금액</span><b>${money(o.subtotal??o.total-(o.shippingFee??settings.shippingFee))}</b></p><p class="detail-cost"><span>배송비</span><b>${money(o.shippingFee??settings.shippingFee)}</b></p><p class="detail-cost total"><span>${o.status==='전체 취소'?'전액 취소금액':'총 결제금액'}</span><b>${money(o.total)}</b></p></div></section><p class="form-note">부분 취소·부분 환불 없이 주문 전체 취소만 가능합니다.</p><div class="dialog-footer"><button data-close="detailDialog">닫기</button>${o.status==='출고 대기'?'<button id="cancelWholeOrder" class="danger">주문 전체 취소</button>':''}</div>`;bindClose();$('cancelWholeOrder')?.addEventListener('click',()=>{if(!confirm('이 주문의 모든 상품을 전액 취소하시겠습니까?'))return;if(o.inventoryApplied!==false)o.items.forEach(i=>{const p=goods.find(p=>p.id===i.id);if(p){p.stock+=i.qty;if(p.status==='soldout')p.status='sale';}});o.status='전체 취소';persist();renderOrders();renderProducts();showDetail(o.number);notify('주문 전체를 취소했습니다.');});if(!$('detailDialog').open)$('detailDialog').showModal();}
$('defaultCarrier').innerHTML=carrierNames.map(c=>`<option ${c===(localStorage.goodsDefaultCarrier||carrierNames[0])?'selected':''}>${c}</option>`).join('');$('defaultCarrier').onchange=()=>{localStorage.goodsDefaultCarrier=$('defaultCarrier').value;document.querySelectorAll('.invoice-carrier').forEach(select=>{const order=orderData.find(o=>o.number===select.closest('tr').dataset.number);if(!order?.trackingNumber)select.value=$('defaultCarrier').value;});};
function renderProducts(){const search=$('productSearch').value.trim(),status=$('productStatus').value,rows=goods.filter(p=>(!search||p.name.includes(search))&&(!status||p.status===status));$('productCount').textContent=rows.length;$('feeSummary').textContent=money(settings.shippingFee);$('cancelSummary').textContent='결제 후 '+settings.cancelHours+'시간 이내 · 발송 전';$('productsTable').innerHTML=rows.length?`<table><thead><tr><th>상품</th><th>판매가격</th><th>재고 수량</th><th>판매 상태</th><th>관리</th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="product-title"><span class="thumb">${p.image?'<img src="'+esc(p.image)+'" alt="">':esc(p.art||'GOODS')}</span><b>${esc(p.name)}</b></div></td><td><b>${money(p.price)}</b></td><td><b>${p.stock}개</b></td><td><select class="badge product-state-select ${p.status==='sale'&&p.stock>0?'':'grey'}" data-product-state="${p.id}" aria-label="${esc(p.name)} 판매 상태 변경" title="${p.stock>0?'클릭하여 판매 상태 변경':'판매 중으로 변경하려면 재고를 먼저 추가해 주세요.'}"><option value="sale" ${p.status==='sale'&&p.stock>0?'selected':''} ${p.stock>0?'':'disabled'}>${p.stock>0?'판매 중':'판매 중 (재고 필요)'}</option><option value="soldout" ${p.status!=='hidden'&&(p.status==='soldout'||p.stock===0)?'selected':''}>품절</option><option value="hidden" ${p.status==='hidden'?'selected':''}>판매 중지</option></select></td><td><button data-edit="${p.id}">상품 · 재고 수정</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">조건에 맞는 상품이 없습니다.</div>';document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEditor(Number(b.dataset.edit)));document.querySelectorAll('[data-product-state]').forEach(select=>select.onchange=()=>changeProductState(Number(select.dataset.productState),select.value));}
function changeProductState(id, status) {
  const product = goods.find(p=>p.id===id);
  if (!product || !['sale','soldout','hidden'].includes(status)) return;
  if (status==='sale' && product.stock<=0) {
    notify('판매 중으로 변경하려면 재고를 먼저 추가해 주세요.'); renderProducts(); return;
  }
  const previous = product.status;
  product.status = status;
  try { localStorage.goodsProducts = JSON.stringify(goods); }
  catch (error) {
    product.status = previous; renderProducts(); notify('판매 상태를 저장하지 못했습니다. 저장 공간을 확인한 뒤 다시 시도해 주세요.'); return;
  }
  renderProducts();
  notify('');
  (document.querySelector('[data-product-state="'+id+'"]') || $('productStatus')).focus();
}
function openEditor(id){const p=goods.find(p=>p.id===id)||{id:'',name:'',price:0,stock:0,image:'',description:'',status:'sale'};$('productEditor').reset();Object.entries(p).forEach(([key,value])=>{if($('productEditor').elements[key])$('productEditor').elements[key].value=value;});CoverImage.load(p.image||'');DetailEditor.load(p.detailHtml||'');$('productSaveError').textContent='';$('editorTitle').textContent=id?'상품 · 재고 수정':'상품 등록';$('productDialog').showModal();}
$('productEditor').onsubmit=e=>{e.preventDefault();if($('productSaveButton').disabled)return;const f=Object.fromEntries(new FormData(e.target));f.detailHtml=DetailEditor.value();f.id=Number(f.id)||Date.now();f.price=Number(f.price);f.stock=Number(f.stock);if(!f.stock&&f.status==='sale')f.status='soldout';const previous=goods.map(p=>({...p}));const index=goods.findIndex(p=>p.id===f.id);if(index>=0)goods[index]={...goods[index],...f};else goods.push({...f,art:'GOODS'});try{localStorage.goodsProducts=JSON.stringify(goods);}catch(error){goods=previous;$('productSaveError').textContent='저장 공간이 부족합니다. 첨부 이미지의 크기나 개수를 줄인 뒤 다시 저장해 주세요.';return;}$('productDialog').close();renderProducts();notify('');};
function openSettings(){Object.entries(settings).forEach(([k,v])=>{if($('settingsForm').elements[k])$('settingsForm').elements[k].value=v;});$('settingsDialog').showModal();}$('openSettings').onclick=openSettings;$('editSettings').onclick=openSettings;$('addGoods').onclick=()=>openEditor();$('settingsForm').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));settings={...settings,...f,shippingFee:Number(f.shippingFee),cancelHours:Number(f.cancelHours)};persist();$('settingsDialog').close();renderProducts();notify('');};
function bindClose(){document.querySelectorAll('[data-close]').forEach(b=>b.onclick=() =>$(b.dataset.close).close());}bindClose();
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{
 const view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));
 salesTab=view==='shipping'?'shipping':'orders';$('salesView').hidden=view==='operations';$('operationsView').hidden=view!=='operations';
 $('salesHeading').textContent=view==='shipping'?'배송 처리':'상품 판매 현황';$('salesDescription').textContent=view==='shipping'?'발송할 주문의 송장번호를 입력하고 발송 완료로 변경합니다.':'주문별 구매 상품, 결제 내역과 배송 상태를 확인합니다.';
 $('shippingFilter').closest('label').hidden=view==='shipping';$('paymentFilter').closest('label').hidden=view==='shipping';
 $('filterForm').reset();renderOrders();document.title=(view==='operations'?'온라인 스토어 운영':view==='shipping'?'배송 처리':'상품 판매 현황')+' | 렛츠런파크 관리자';notify('');
});$('filterForm').onsubmit=e=>{e.preventDefault();renderOrders();};$('resetFilters').onclick=()=>{$('filterForm').reset();renderOrders();};$('productSearch').oninput=renderProducts;$('productStatus').onchange=renderProducts;
$('exportOrders').onclick=()=>{const rows=[['주문번호','구매자','전화번호','상품','수량','수령인','주소','배송메모','결제금액','상태','택배사','송장번호']];filteredOrders().forEach(o=>o.items.forEach(i=>rows.push([o.number,o.name,o.phone,i.name,i.qty,o.recipient||o.name,o.address,o.request||'',o.total,state(o),o.carrier||'',o.trackingNumber||''])));const csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=salesTab==='shipping'?'상품_발송대상.csv':'상품_주문목록.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
